insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('476', '신스틸러', 'Sin-seu-til-leo', 'drama', null, '주연보다 장면을 사로잡는 조연', '{"de": "Eine Nebenrolle, die den Hauptrollen die Szene stiehlt", "en": "A side character who owns the scene more than the leads", "es": "Un secundario que se roba la escena a los protagonistas", "ja": "主演より場面をさらう脇役", "vi": "Vai phụ cướp sóng cả vai chính"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Nur drei Minuten Screentime und trotzdem die heimliche Hauptrolle.", "es": "Solo tres minutos en pantalla y aun así se robó la función.", "ja": "出番は3分なのに完全にシーンスティーラーだった。", "vi": "Đất diễn có ba phút mà cướp trọn cả phim.", "eng": "Three minutes of screen time and they still stole the whole show.", "kor": "분량은 3분인데 완전 신스틸러였어."}, {"de": "Der wahre Szenendieb in diesem Film ist die Katze der Hauptfigur.", "es": "El verdadero ladrón de escenas de esta peli es el gato del protagonista.", "ja": "この映画の本当のシーンスティーラーは主人公の猫だよ。", "vi": "Kẻ cướp cảnh thật sự của phim này là con mèo của nhân vật chính.", "eng": "The real scene stealer in this film is the main character''s cat.", "kor": "이 영화 진짜 신스틸러는 주인공 고양이야."}], "definition": "영어 scene stealer를 그대로 옮긴 말로, 주연은 아니지만 개성·연기력·카리스마로 장면을 통째로 가져가는 조연을 뜻한다. 국립국어원은 다듬은 말로 ''명품 조연''을 제시했지만 실제로는 ''신스틸러''가 훨씬 널리 쓰인다. 배우뿐 아니라 예능 출연자나 사진 속 강아지처럼 시선을 뺏는 존재 전반에 쓰기도 한다.", "definition_i18n": {"de": "Direkte Entlehnung von englisch ''scene stealer'': eine Nebenrolle, die die Szene an sich reißt. Das Nationale Institut für die koreanische Sprache schlug 명품 조연 als Ersatz vor, doch 신스틸러 ist weit verbreiteter. Gilt auch für alles andere, was die Aufmerksamkeit klaut.", "en": "A direct borrowing of English ''scene stealer'': a non-lead whose charisma or skill takes over the scene. The National Institute of Korean Language proposed 명품 조연 as a native replacement, but 신스틸러 remains far more common. It also stretches to anything that grabs attention — a variety-show guest, even a dog in a photo.", "es": "Préstamo directo del inglés ''scene stealer'': un secundario que, sin ser protagonista, se apodera de la escena. El Instituto Nacional de la Lengua Coreana propuso 명품 조연 como alternativa, pero 신스틸러 sigue siendo mucho más usado. También se aplica a cualquier cosa que acapare la atención.", "ja": "英語scene stealerをそのまま借りた語で、主演ではないが個性・演技力・存在感で場面をさらう脇役。国立国語院は言い換え語に「명품 조연(名品脇役)」を提示したが、実際は「신스틸러」の方がはるかに多く使われる。俳優以外にも視線を奪う存在全般に使う。", "vi": "Vay thẳng từ tiếng Anh ''scene stealer'': vai phụ nhưng cá tính, diễn hay tới mức chiếm trọn cảnh quay. Viện Quốc ngữ đề xuất thay bằng 명품 조연, song 신스틸러 vẫn phổ biến hơn nhiều. Còn dùng cho bất cứ thứ gì hút hết sự chú ý."}}]'::jsonb, '영어 scene stealer의 차용어. ''scene''의 한국식 표기가 ''신/씬''으로 갈려 ''신스틸러''와 ''씬스틸러''가 함께 쓰인다. 외래어 표기법상으로는 ''신스틸러''가 맞고, 국립국어원 우리말 다듬기에서 ''명품 조연''을 다듬은 말로 선정했다.', '{"de": "Lehnwort aus dem Englischen ''scene stealer''. Da ''scene'' zweifach transkribiert wird, kursieren 신스틸러 und 씬스틸러; Ersteres folgt der offiziellen Norm. Das Sprachinstitut empfahl 명품 조연 als Ersatz.", "en": "A loanword from English ''scene stealer''. Because ''scene'' is transcribed two ways in Korean, both 신스틸러 and 씬스틸러 circulate; 신스틸러 follows the official loanword rules. The National Institute of Korean Language chose 명품 조연 as the recommended native equivalent.", "es": "Préstamo del inglés ''scene stealer''. Como ''scene'' se transcribe de dos formas, circulan 신스틸러 y 씬스틸러; la primera sigue la norma oficial. El Instituto Nacional eligió 명품 조연 como equivalente recomendado.", "ja": "英語scene stealerの借用語。''scene''の表記が「신/씬」に分かれるため「신스틸러」と「씬스틸러」が併用される。外来語表記法では「신스틸러」が正しく、国立国語院は言い換え語に「명품 조연」を選定した。", "vi": "Từ mượn tiếng Anh ''scene stealer''. Vì ''scene'' được phiên hai kiểu nên tồn tại cả 신스틸러 và 씬스틸러; 신스틸러 đúng chuẩn phiên âm. Viện Quốc ngữ chọn 명품 조연 làm từ thay thế."}'::jsonb, '칭찬하는 말이라 배우 본인이나 팬 앞에서 마음 놓고 써도 된다. 작품 감상평·댓글에서 ''이번 드라마 신스틸러는 ○○''처럼 쓰는 게 가장 흔하다. 표준국어대사전에는 없다.', '{"de": "Reines Lob — man kann es Schauspielern oder Fans gegenüber bedenkenlos sagen. Üblich ist \"der Szenendieb dieser Serie ist ___\" in Rezensionen. Nicht im Standardwörterbuch.", "en": "It is pure praise, so it is safe to say to the actor or their fans. The most common frame is \"the scene stealer of this drama is ___\" in reviews and comments. Not in the Standard Korean Dictionary.", "es": "Es puro elogio, así que puedes decirlo delante del actor o de sus fans. Lo más común es \"el scene stealer de esta serie es ___\" en reseñas y comentarios. No está en el diccionario estándar.", "ja": "褒め言葉なので本人やファンの前で使っても問題ない。「今回のドラマの신스틸러は○○」のように感想やコメントで使うのが最も一般的。標準国語大辞典には未収録。", "vi": "Đây là lời khen nên nói trước mặt diễn viên hay fan đều ổn. Hay gặp nhất là \"scene stealer của phim này là ___\" trong bình luận. Không có trong từ điển chuẩn."}'::jsonb, array['인생캐','발연기','분량'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Scene stealer"}, {"lang": "🇯🇵 JA", "text": "シーンスティーラー、名脇役"}, {"lang": "🇨🇳 ZH", "text": "抢戏配角"}, {"lang": "🇻🇳 VI", "text": "Kẻ cướp cảnh, vai phụ đắt giá"}, {"lang": "🇪🇸 ES", "text": "Ladrón de escenas"}, {"lang": "🇩🇪 DE", "text": "Szenendieb"}]'::jsonb),
('477', '캐붕', 'Kae-bung', 'drama', null, '''캐릭터 붕괴'' — 인물이 설정과 딴판으로 변하는 것', '{"de": "Kurz für Charakterzusammenbruch — eine Figur handelt völlig untypisch", "en": "Short for character collapse — a character acting out of character", "es": "Abreviatura de colapso de personaje: actuar fuera de personaje", "ja": "「キャラ崩壊」の略 — 人物が設定と別人のように変わること", "vi": "Viết tắt của ''sụp đổ nhân vật'' — nhân vật hành xử trái tính cách"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Dass er im Finale plötzlich nett wird, ist totaler Charakterbruch.", "es": "Que se vuelva bueno de repente en el final es un colapso de personaje total.", "ja": "最終話でいきなり善人になるのは完全にキャラ崩壊。", "vi": "Tập cuối tự nhiên hoá người tốt là sụp nhân vật hoàn toàn.", "eng": "Him suddenly turning nice in the finale is total character collapse.", "kor": "마지막 화에서 갑자기 착해지는 거 완전 캐붕이야."}, {"de": "Wer hat Staffel 2 geschrieben? Der Charakterbruch ist unerträglich.", "es": "¿Quién escribió la temporada 2? El colapso de personajes es insoportable.", "ja": "シーズン2の脚本誰が書いた?キャラ崩壊がひどくて見てられない。", "vi": "Ai viết mùa 2 vậy? Nhân vật sụp tới mức không xem nổi.", "eng": "Who wrote season 2? The characters are so broken I can''t watch.", "kor": "시즌2 대본 누가 썼어? 캐붕 심해서 못 보겠다."}], "definition": "''캐릭터 붕괴''의 줄임말. 드라마·영화·웹툰·게임에서 등장인물이 지금까지 쌓아온 성격이나 설정과 어울리지 않게 갑자기 딴사람처럼 행동하는 것을 말한다. 늘 냉철하던 인물이 뜬금없이 실없어지거나, 악역이 개연성 없이 착해지는 식이다. 보통 작가의 실수나 급한 마무리를 탓하는 부정적인 말이다.", "definition_i18n": {"de": "Kurz für 캐릭터 붕괴: Wenn eine Figur in Serie, Film, Webtoon oder Spiel plötzlich allem widerspricht, was über sie etabliert wurde — die Kühle wird albern, der Schurke ohne Aufbau gut. Meist Kritik an hastigem Schreiben.", "en": "Short for 캐릭터 붕괴, character collapse: when a character in a drama, film, webtoon or game suddenly behaves in a way that contradicts everything established about them — the cool-headed one turning silly, the villain turning good with no build-up. It is usually a criticism aimed at sloppy or rushed writing.", "es": "Abreviatura de 캐릭터 붕괴: cuando un personaje de una serie, película, webtoon o juego actúa de golpe en contra de todo lo establecido — el frío se vuelve bobo, el villano se vuelve bueno sin preparación. Suele ser una crítica a una escritura apresurada.", "ja": "「キャラクター崩壊」の略。ドラマ・映画・ウェブトゥーン・ゲームで、登場人物がこれまでの性格や設定と噛み合わない別人のような行動を取ること。冷静だった人物が突然おどけたり、悪役が脈絡なく善人になったり。作者のミスや駆け足の展開を責める否定的な語。", "vi": "Viết tắt của 캐릭터 붕괴: khi nhân vật trong phim, webtoon hay game đột nhiên hành xử trái ngược mọi thứ đã xây dựng — người lạnh lùng bỗng lố lăng, phản diện hoá tốt vô lý. Thường là lời chê kịch bản cẩu thả."}}]'::jsonb, '''캐릭터''와 ''붕괴''를 각각 한 글자씩 따 붙인 줄임말로, 팬픽·동인 창작과 웹툰 커뮤니티에서 먼저 쓰이다 드라마 감상평 전반으로 넓어졌다. 일본 오타쿠 용어 ''캐릭터 붕괴(キャラ崩壊)''와 발상이 같지만, 한국어 줄임말 형태가 정확히 언제 굳었는지 특정한 출처는 없다.', '{"de": "Kurzform aus 캐릭터 + 붕괴, zuerst in Fanfic- und Webtoon-Kreisen verbreitet, dann in der allgemeinen Seriendiskussion. Parallel zum japanischen Otaku-Begriff キャラ崩壊, doch keine Quelle datiert die koreanische Kurzform.", "en": "A clipping of 캐릭터 (character) + 붕괴 (collapse), first common in fanfic and webtoon communities before spreading to general drama commentary. It parallels the Japanese otaku term キャラ崩壊, but no source pins down when the Korean clipped form settled.", "es": "Recorte de 캐릭터 + 붕괴, primero habitual en comunidades de fanfic y webtoon y luego en la crítica de series. Es paralelo al término otaku japonés キャラ崩壊, pero ninguna fuente fija cuándo cuajó la forma coreana.", "ja": "「캐릭터」と「붕괴」から一字ずつ取った略語。ファンフィクやウェブトゥーンのコミュニティで先に使われ、ドラマ感想全般に広がった。日本のオタク用語「キャラ崩壊」と発想は同じだが、韓国語の略語形がいつ定着したかを示す出典はない。", "vi": "Ghép rút gọn 캐릭터 + 붕괴, ban đầu phổ biến trong cộng đồng fanfic và webtoon rồi lan ra bình luận phim. Tương đồng với thuật ngữ otaku Nhật キャラ崩壊, nhưng không nguồn nào xác định thời điểm dạng rút gọn tiếng Hàn định hình."}'::jsonb, '작품을 비판할 때 쓰는 말이라 창작자 앞에서는 조심스럽다. 다만 팬들끼리 좋아하는 캐릭터가 귀엽게 망가질 때 ''귀여운 캐붕''처럼 애정 섞어 쓰기도 한다. ''고구마'', ''막장''과 함께 전개 불만을 말할 때 자주 나온다.', '{"de": "Es kritisiert das Werk, wirkt vor Kreativen also unangenehm. Unter Fans kann es liebevoll sein: 귀여운 캐붕. Taucht oft mit 고구마 und 막장 auf, wenn man über die Handlung schimpft.", "en": "It criticises the work, so it lands awkwardly in front of creators. Among fans, though, it can be affectionate — 귀여운 캐붕 for a beloved character breaking cutely. Often appears with 고구마 and 막장 when complaining about a plot.", "es": "Critica la obra, así que suena incómodo ante los creadores. Entre fans puede ser cariñoso: 귀여운 캐붕 para un personaje querido que se rompe de forma tierna. Sale junto a 고구마 y 막장 al quejarse de la trama.", "ja": "作品批判の語なので制作者の前では気まずい。ただしファン同士では「かわいいキャラ崩壊」のように愛情混じりで使うこともある。「고구마」「막장」と並んで展開への不満を語るときによく出る。", "vi": "Là lời chê tác phẩm nên nói trước mặt người sáng tác thì khó xử. Trong fandom lại có thể mang nghĩa cưng: 귀여운 캐붕. Hay đi kèm 고구마 và 막장 khi than phiền tình tiết."}'::jsonb, array['막장','고구마','과몰입'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Out of character / character break"}, {"lang": "🇯🇵 JA", "text": "キャラ崩壊"}, {"lang": "🇨🇳 ZH", "text": "人设崩塌、崩人设"}, {"lang": "🇻🇳 VI", "text": "Sụp nhân vật, vỡ nhân thiết"}, {"lang": "🇪🇸 ES", "text": "Colapso de personaje"}, {"lang": "🇩🇪 DE", "text": "Charakterbruch"}]'::jsonb);

-- After apply: select count(*) from public.words; → 394
